INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3f5434e3-ec6b-44b7-870b-47004ab1632f', 'c1c2c3d4-3030-4000-8000-000000000030', 26, 'Paz', 'Semana 4 — Integrar', '{"pch": "A paz de Cristo n\u00e3o \u00e9 aus\u00eancia de luta\u2026 \u00e9 presen\u00e7a em meio a ela.", "verse": "Jo 14,27", "lectio": "Leia e pergunte: a paz que eu busco \u00e9 do mundo ou de Deus?", "practice": "Identifique uma fonte de agita\u00e7\u00e3o e entregue-a em sil\u00eancio.", "question": "O que rouba sua paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e576064d-c53e-44c8-8997-eb90d6527d84', 'c1c2c3d4-3030-4000-8000-000000000030', 27, 'Direção', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o precisa ver todo o caminho\u2026 s\u00f3 o pr\u00f3ximo passo.", "verse": "Sl 119,105", "lectio": "A Palavra \u00e9 l\u00e2mpada. Que luz ela traz para sua decis\u00e3o de hoje?", "practice": "Tome uma decis\u00e3o que voc\u00ea adia, confiando na luz que j\u00e1 tem.", "question": "Qual \u00e9 o pr\u00f3ximo passo que voc\u00ea j\u00e1 sabe?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a0445828-d326-4697-9786-60b513aaba02', 'c1c2c3d4-3030-4000-8000-000000000030', 28, 'Compromisso', 'Semana 4 — Integrar', '{"pch": "Decidir \u00e9 cortar todas as outras op\u00e7\u00f5es\u2026 e caminhar.", "verse": "Js 24,15", "lectio": "Josu\u00e9 escolhe servir ao Senhor. Qual \u00e9 a sua escolha hoje?", "practice": "Escreva um compromisso concreto para os pr\u00f3ximos 30 dias.", "question": "Com o que voc\u00ea se compromete a partir de agora?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('013d164a-ae98-43c4-9957-2211f898021e', 'c1c2c3d4-3030-4000-8000-000000000030', 29, 'Consolidação', 'Semana 4 — Integrar', '{"pch": "Ouvir sem fazer\u2026 \u00e9 o sono da alma.", "verse": "Tg 1,22-25", "lectio": "Seja praticante da Palavra. Qual ensinamento desta jornada precisa virar a\u00e7\u00e3o?", "practice": "Releia suas reflex\u00f5es da semana 1. O que mudou?", "question": "O que voc\u00ea aprendeu mas ainda n\u00e3o praticou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('5529aca4-697e-4176-af9d-096c5a60c73f', 'c1c2c3d4-3030-4000-8000-000000000030', 30, 'Novo Começo', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o chegou ao fim\u2026 voc\u00ea saiu de onde estava.", "verse": "Ap 21,5", "lectio": "Eu fa\u00e7o novas todas as coisas. O que \u00e9 novo em voc\u00ea agora?", "practice": "Escreva uma carta para si mesmo: quem eu era no dia 1, quem eu sou no dia 30, e para onde vou.", "question": "Quem voc\u00ea se tornou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('2711a145-076a-4092-99b4-9a1f1992ae2b', 'c3c3c3c3-3030-4000-8000-000000000003', 1, 'Dia 1 — Ruído', 'Semana 1: Parar', '{"pch": "Depois do fogo\u2026 uma voz mansa e suave. Deus n\u00e3o grita. Ele sussurra. Mas voc\u00ea precisa parar para ouvir.", "verse": "1Rs 19,12", "lectio": "Leia 1Rs 19,9-13. Elias no monte.", "practice": "Liste tudo que est\u00e1 na sua cabe\u00e7a agora. Tudo. Sem filtro.", "question": "Que ru\u00eddo constante ocupa sua mente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('61ed9a2c-de4a-446e-bda9-c8902adbe470', 'c3c3c3c3-3030-4000-8000-000000000003', 2, 'Dia 2 — Overload', 'Semana 1: Parar', '{"pch": "Acalmei e sosseguei a minha alma\u2026 como uma crian\u00e7a no colo da m\u00e3e. Menos \u00e9 mais.", "verse": "Sl 131,1-2", "lectio": "Leia Sl 131. O salmo mais curto e mais profundo.", "practice": "Elimine 1 compromisso desnecess\u00e1rio esta semana.", "question": "O que te sobrecarrega mais: o que acontece ou o que voc\u00ea pensa sobre o que acontece?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('512f28b3-a771-4f78-8330-a88f58f6d656', 'c3c3c3c3-3030-4000-8000-000000000003', 3, 'Dia 3 — Ansiedade', 'Semana 1: Parar', '{"pch": "Basta a cada dia o seu pr\u00f3prio mal\u2026 Pensar no amanh\u00e3 \u00e9 roubar a paz de hoje.", "verse": "Mt 6,34", "lectio": "Leia Mt 6,25-34. Olhai os l\u00edrios do campo.", "practice": "Anote 3 preocupa\u00e7\u00f5es. Ao lado de cada uma, escreva: posso controlar isso? Sim ou n\u00e3o.", "question": "Sobre o que voc\u00ea se preocupa que n\u00e3o pode controlar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a7f8dab1-f5f2-4cd5-aed2-6bd4d8588f66', 'c3c3c3c3-3030-4000-8000-000000000003', 4, 'Dia 4 — Respirar', 'Semana 1: Parar', '{"pch": "Soprou nas suas narinas o f\u00f4lego de vida\u2026 A respira\u00e7\u00e3o \u00e9 o primeiro presente de Deus.", "verse": "Gn 2,7", "lectio": "Leia Gn 2,4-7. Deus formou e soprou.", "practice": "Pratique 5 minutos de respira\u00e7\u00e3o consciente: 4s inspira, 7s segura, 8s expira.", "question": "Quando foi a \u00faltima vez que voc\u00ea respirou com consci\u00eancia?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('2988c988-44af-4744-bbf5-031bcccf7926', 'c3c3c3c3-3030-4000-8000-000000000003', 5, 'Dia 5 — Pensamentos', 'Semana 1: Parar', '{"pch": "Pensai em tudo o que \u00e9 verdadeiro, nobre, justo\u2026 Voc\u00ea \u00e9 o que pensa repetidamente.", "verse": "Fl 4,8", "lectio": "Leia Fl 4,4-9. A receita da paz.", "practice": "Observe seus pensamentos por 10 min sem reagir. Apenas note.", "question": "Quais pensamentos se repetem na sua mente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b4a145ff-c7e3-4083-bb66-921abf7f0735', 'c3c3c3c3-3030-4000-8000-000000000003', 6, 'Dia 6 — Digital', 'Semana 1: Parar', '{"pch": "O olho n\u00e3o se farta de ver\u2026 nem o ouvido de ouvir. O scroll infinito \u00e9 a torre de Babel moderna.", "verse": "Ec 1,8", "lectio": "Leia Ec 1,1-11. Vaidade das vaidades.", "practice": "Fique 2 horas sem celular. Observe o que acontece dentro de voc\u00ea.", "question": "Quanto tempo por dia sua mente \u00e9 alimentada por telas?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('cc39322a-514a-4e0e-bc2d-ce1ab1c1eb2d', 'c3c3c3c3-3030-4000-8000-000000000003', 7, 'Dia 7 — Sabbath mental', 'Semana 1: Parar', '{"pch": "Lembra-te do dia de s\u00e1bado para o santificar\u2026 Sua mente tamb\u00e9m precisa de descanso sagrado.", "verse": "Ex 20,8", "lectio": "Leia Ex 20,8-11. O mandamento do descanso.", "practice": "Crie um mini-sabbath: 3 horas sem produtividade, s\u00f3 presen\u00e7a.", "question": "Quando foi a \u00faltima vez que sua mente descansou de verdade?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('df69c5d1-aa43-4247-a7b5-9ecfd1c5a72b', 'c3c3c3c3-3030-4000-8000-000000000003', 8, 'Dia 8 — Prioridades', 'Semana 2: Organizar', '{"pch": "Maria escolheu a melhor parte\u2026 Nem tudo que \u00e9 urgente \u00e9 importante.", "verse": "Lc 10,42", "lectio": "Leia Lc 10,38-42. Marta e Maria.", "practice": "Liste suas 5 prioridades. Compare com como gasta seu tempo.", "question": "O que \u00e9 realmente importante na sua vida agora?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('004afa2a-d390-4faa-bbbb-770dff01f616', 'c3c3c3c3-3030-4000-8000-000000000003', 9, 'Dia 9 — Simplicidade', 'Semana 2: Organizar', '{"pch": "Se n\u00e3o vos converterdes como crian\u00e7as\u2026 A crian\u00e7a n\u00e3o complica. Ela vive.", "verse": "Mt 18,3", "lectio": "Leia Mt 18,1-5. Tornar-se como crian\u00e7a.", "practice": "Simplifique 1 \u00e1rea da sua vida hoje. Menos \u00e9 clareza.", "question": "O que voc\u00ea est\u00e1 complicando desnecessariamente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6e35250f-3494-46c4-8a9e-16fd80ebbf64', 'c3c3c3c3-3030-4000-8000-000000000003', 10, 'Dia 10 — Foco', 'Semana 2: Organizar', '{"pch": "Olhando para Jesus\u2026 autor e consumador da f\u00e9. Foco \u00e9 decidir para onde olhar.", "verse": "Hb 12,2", "lectio": "Leia Hb 12,1-3. Correr com perseveran\u00e7a.", "practice": "Escolha 1 coisa importante. Dedique 1 hora ininterrupta a ela.", "question": "No que voc\u00ea deveria estar focado mas n\u00e3o est\u00e1?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6de31ec2-ad63-42ce-8a40-c843f91b4eaa', 'c3c3c3c3-3030-4000-8000-000000000003', 11, 'Dia 11 — Decisões', 'Semana 2: Organizar', '{"pch": "Se algu\u00e9m tem falta de sabedoria, pe\u00e7a a Deus\u2026 Clareza vem de quem v\u00ea tudo.", "verse": "Tg 1,5", "lectio": "Leia Tg 1,2-8. Pedir com f\u00e9, sem duvidar.", "practice": "Ore especificamente sobre uma decis\u00e3o. Depois, escreva o que sentiu.", "question": "Que decis\u00e3o te paralisa por falta de clareza?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('09fbf4de-26cd-4257-ad1f-04d5c75458f6', 'c3c3c3c3-3030-4000-8000-000000000003', 12, 'Dia 12 — Mente renovada', 'Semana 2: Organizar', '{"pch": "Transformai-vos pela renova\u00e7\u00e3o da mente\u2026 Pensar diferente \u00e9 o come\u00e7o de viver diferente.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Identifique 1 pensamento negativo recorrente. Substitua por uma verdade b\u00edblica.", "question": "Que padr\u00e3o de pensamento precisa mudar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f27b563c-6f42-42ae-9c21-029b44359198', 'c3c3c3c3-3030-4000-8000-000000000003', 13, 'Dia 13 — Verdade', 'Semana 2: Organizar', '{"pch": "Conhecereis a verdade e a verdade vos libertar\u00e1\u2026 Mentiras internas aprisionam. A verdade liberta.", "verse": "Jo 8,32", "lectio": "Leia Jo 8,31-36. A liberdade real.", "practice": "Escreva a mentira. Ao lado, escreva a verdade de Deus sobre voc\u00ea.", "question": "Que mentira sobre si mesmo voc\u00ea acreditou por tempo demais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('576dc901-367c-491c-88a5-7633757d1521', 'c3c3c3c3-3030-4000-8000-000000000003', 14, 'Dia 14 — Silêncio', 'Semana 2: Organizar', '{"pch": "Aquietai-vos\u2026 No sil\u00eancio, os pensamentos se acomodam como sedimento na \u00e1gua.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio.", "practice": "15 minutos de sil\u00eancio contemplativo. Sem guia, sem m\u00fasica.", "question": "O que aparece quando tudo fica em sil\u00eancio?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('51f9a773-6c24-4386-adc1-05b27c4bc477', 'c3c3c3c3-3030-4000-8000-000000000003', 15, 'Dia 15 — Sabedoria', 'Semana 3: Discernir', '{"pch": "O princ\u00edpio da sabedoria \u00e9: adquire sabedoria\u2026 A sabedoria n\u00e3o \u00e9 informa\u00e7\u00e3o \u2014 \u00e9 discernimento.", "verse": "Pv 4,7", "lectio": "Leia Pv 4,1-9. A sabedoria como tesouro.", "practice": "Pe\u00e7a conselho a algu\u00e9m mais velho e s\u00e1bio sobre algo que te inquieta.", "question": "Qual a diferen\u00e7a entre saber e ser s\u00e1bio na sua vida?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
